#include "stdafx.h"#include "H_Class.h"static SBlockCreate GENLIN( "GENLIN", SH_GENLIN::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_GENLIN,W_GENLIN,55)void SH_GENLIN::InitParm(){#include "Blocks/GENLIN.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/GENLIN_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class GENLIN_IMPL : public W_GENLIN{public:  void StepT( SStepCalcParams &dt );protected:  bool IsBAD( int i );};void SH_GENLIN::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  GENLIN_IMPL *impl = reinterpret_cast<GENLIN_IMPL*>(W);  impl->StepT( dt );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void GENLIN_IMPL::StepT( SStepCalcParams &dt ){  if( IsNaN(P1) )  {    PVSTS = _PVSTS::BAD;    PVSTSFL.BAD = true;    PVSTSFL.NORM = false;    return;  }  if( _P1STS::BAD == P1STS.V )  {    PVSTS = _PVSTS::BAD;    PVSTSFL.BAD = false;    PVSTSFL.NORM = true;    return;  }  PVSTS = _PVSTS::NORMAL;  PVSTSFL.BAD = false;  PVSTSFL.NORM = true;  if( P1 < IN[1] )  {    if( IsBAD(1) || IsBAD(0) )      return;    PV = ((OUT[1]-OUT[0])/(IN[1]-IN[0])) * ( P1-IN[0] ) + OUT[0];  }  else if( P1 > IN[NUMSEGS-1] )  {    int i = NUMSEGS-1;    if( IsBAD(i) || IsBAD(NUMSEGS) )      return;    PV = ((OUT[NUMSEGS]-OUT[i])/(IN[NUMSEGS]-IN[i])) * ( P1-IN[i] ) + OUT[i];  }  else  {    for( int i=1, end(NUMSEGS-2); i<end; ++i )    {      if( IsBAD(i) )        return;      if( !(P1>=IN[i] && P1<IN[i+1]) )        continue;      PV = ((OUT[i+1]-OUT[i])/(IN[i+1]-IN[i])) * ( P1-IN[i] ) + OUT[i];      break;    }  }}bool GENLIN_IMPL::IsBAD( int i ){  if( IsNaN(IN[i]) || IsNaN(OUT[i]) )  {    PVSTS = _PVSTS::BAD;    PVSTSFL.BAD = true;    PVSTSFL.NORM = false;    return true;  }  PVSTS = _PVSTS::NORMAL;  PVSTSFL.BAD = false;  PVSTSFL.NORM = true;  return false;}